namespace BlazorApp.Services;

public class NotificationItem
{
    public int Id { get; set; }
    public string Message { get; set; } = string.Empty;
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 4;
    private readonly List<NotificationItem> _notifications = new()
    {
        new() { Id = 1, Message = "Welcome to the app!", Timestamp = DateTime.Now.AddMinutes(-10) },
        new() { Id = 2, Message = "Your profile was updated.", Timestamp = DateTime.Now.AddMinutes(-5) },
        new() { Id = 3, Message = "New feature available: dark mode.", Timestamp = DateTime.Now.AddMinutes(-2) },
    };

    public Task<List<NotificationItem>> GetNotificationsAsync()
    {
        lock (_notifications)
        {
            return Task.FromResult(_notifications.ToList());
        }
    }

    public Task<List<NotificationItem>> GetNotificationsSinceAsync(int lastId)
    {
        lock (_notifications)
        {
            var newer = _notifications.Where(n => n.Id > lastId).ToList();
            return Task.FromResult(newer);
        }
    }

    public void SimulateNewNotification()
    {
        lock (_notifications)
        {
            _notifications.Add(new NotificationItem
            {
                Id = _nextId,
                Message = $"New event #{_nextId} occurred.",
                Timestamp = DateTime.Now
            });
            _nextId++;
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using BlazorApp.Services
@inject NotificationService NotificationService
@implements IDisposable

<PageTitle>Notifications</PageTitle>

<h1>Notifications <span class="badge bg-primary">@notifications.Count</span></h1>

@if (notifications.Count == 0)
{
    <p>No notifications yet.</p>
}
else
{
    <ul class="list-group">
        @foreach (var item in notifications.OrderByDescending(n => n.Timestamp))
        {
            <li class="list-group-item">
                <strong>@item.Message</strong>
                <small class="text-muted ms-2">@item.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    [PersistentState]
    public List<NotificationItem>? Notifications { get; set; }

    private List<NotificationItem> notifications => Notifications ?? new();
    private CancellationTokenSource? _cts;
    private int _lastId;

    protected override async Task OnInitializedAsync()
    {
        Notifications ??= await NotificationService.GetNotificationsAsync();
        _lastId = Notifications.Count > 0 ? Notifications.Max(n => n.Id) : 0;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(5000, ct).ConfigureAwait(false);

            // Simulate a new notification arriving on each poll
            NotificationService.SimulateNewNotification();

            var newer = await NotificationService.GetNotificationsSinceAsync(_lastId);
            if (newer.Count > 0)
            {
                _lastId = newer.Max(n => n.Id);
                await InvokeAsync(() =>
                {
                    Notifications!.AddRange(newer);
                    StateHasChanged();
                });
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

